\set ON_ERROR_STOP on
begin;
set local search_path=v2,extensions,public;
create schema test;
create function test.ok(label text,value boolean) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end$$;
create function test.reject(label text,statement text,expected text) returns void language plpgsql as $$
declare caught boolean=false;
begin
 begin execute statement;exception when others then
  if position(expected in sqlerrm)=0 then raise exception 'FAIL: %, unexpected: %',label,sqlerrm;end if;caught=true;
 end;
 perform test.ok(label,caught);
end$$;
create function test.fix(lat double precision default 30,lon double precision default 120,acc integer default 10) returns jsonb language sql as $$select jsonb_build_object('latitude',lat,'longitude',lon,'accuracy',acc,'capturedAt',now(),'ageMillis',0,'mock',false)$$;
create function test.asset(actor uuid) returns uuid language plpgsql as $$declare r jsonb;begin r=public.pilgrimage_v2(actor,'media_reserve',jsonb_build_object('request_id',gen_random_uuid(),'size_bytes',100,'sha256',repeat('a',64)));perform public.pilgrimage_v2(actor,'media_ready',r);return (r->>'id')::uuid;end$$;
insert into auth.users(id,email_confirmed_at) values ('11111111-1111-1111-1111-111111111111',now()),('22222222-2222-2222-2222-222222222222',now()),('33333333-3333-3333-3333-333333333333',now());
insert into profiles(id,nickname,role) values ('11111111-1111-1111-1111-111111111111','旅人甲','member'),('22222222-2222-2222-2222-222222222222','旅人乙','member'),('33333333-3333-3333-3333-333333333333','管理员','admin');
insert into locations(id,name,city,country,latitude,longitude) values('test-place','隔离测试地点','测试城市','中国',30,120);
insert into artists values('test-artist','测试歌手','[]');insert into works(id,title) values('test-work','测试作品');
insert into scenes(id,location_id,work_id,artist_id,image_url) values('test-scene','test-place','test-work','test-artist','https://example.invalid/reference.jpg');
insert into questions(id,challenge_type,question,options,correct_option,explanation,published) values('test-choice','multiple_choice','隔离测试：选择甲','[{"id":"0","text":"甲"},{"id":"1","text":"乙"},{"id":"2","text":"丙"},{"id":"3","text":"丁"}]','0','此题仅用于验证计分，不是线上题库。',true);
select test.ok('real PostGIS extension',postgis_version() like '3.%');
select test.ok('guest catalog works',jsonb_array_length(public.pilgrimage_v2(null,'catalog')->'places')=21);
select test.reject('guest cannot read UGC',$q$select public.pilgrimage_v2(null,'content')$q$,'请先登录');
select test.ok('no direct answer grants',not has_table_privilege('authenticated','v2.questions','select'));
select test.ok('no direct role writes',not has_table_privilege('authenticated','v2.profiles','update'));
select test.ok('cannot spoof RPC actor',not has_function_privilege('authenticated','public.pilgrimage_v2(uuid,text,jsonb)','execute'));
select test.ok('Auth hook closes registration',(public.pilgrimage_before_user_created('{}')->'error'->>'http_code')::int=403);
select test.ok('registration allowlist has no client grants',not has_table_privilege('authenticated','v2.registration_allowlist','select') and not has_table_privilege('anon','v2.registration_guard','select'));
update app_config set registration_enabled=true;
update registration_guard set test_mode=true;
insert into registration_allowlist values('qa+v2@example.invalid',now()+interval '1 hour');
select test.ok('test hook rejects non-allowlisted Auth API signup',(public.pilgrimage_before_user_created('{"user":{"email":"other@example.invalid"}}')->'error'->>'http_code')::int=403);
select test.ok('test hook accepts allowlisted case-normalized email',public.pilgrimage_before_user_created('{"user":{"email":"QA+V2@example.invalid"}}')='{}');
update registration_allowlist set expires_at=now()-interval '1 second';
select test.ok('expired test invitation cannot register',(public.pilgrimage_before_user_created('{"user":{"email":"qa+v2@example.invalid"}}')->'error'->>'http_code')::int=403);
update registration_guard set test_mode=false;
update app_config set registration_enabled=false;
select test.ok('accuracy 100 accepted',validate_fix(test.fix(30,120,100)) is not null);
select test.reject('accuracy over 100 rejected',$q$select validate_fix(test.fix(30,120,101))$q$,'精度');
select test.reject('old GPS rejected',$q$select validate_fix(test.fix()||'{"ageMillis":120001}')$q$,'过期');
select test.reject('mock GPS rejected',$q$select validate_fix(test.fix()||'{"mock":true}')$q$,'模拟');
select test.reject('future timestamp rejected',$q$select validate_fix(test.fix()||jsonb_build_object('capturedAt',now()+interval '1 minute'))$q$,'过期');
do $$
declare a uuid='11111111-1111-1111-1111-111111111111';b uuid='22222222-2222-2222-2222-222222222222';admin uuid='33333333-3333-3333-3333-333333333333';
 r jsonb;p jsonb;message uuid;visit uuid;recreation uuid;asset1 uuid;asset2 uuid;point geography;report_id uuid;i integer;
begin
 perform public.pilgrimage_v2(admin,'admin_config','{"image_upload_enabled":false}');
 perform test.ok('admin feature update selects singleton row',(select image_upload_enabled=false and registration_enabled=false from app_config where id=true));
 perform test.reject('member cannot change feature flags',format('select public.pilgrimage_v2(%L,''admin_config'',''{"image_upload_enabled":true}'')',a),'管理员');
 perform public.pilgrimage_v2(admin,'admin_config','{"image_upload_enabled":true}');
 perform test.ok('admin feature update creates audit',exists(select 1 from audit_log where actor_id=admin and action='admin_config'));
 p=jsonb_build_object('id',gen_random_uuid(),'location_id','test-place','body','留言','song','歌曲');
 r=public.pilgrimage_v2(a,'create_message',p);message=(r->>'id')::uuid;
 perform test.ok('message retry idempotent',(public.pilgrimage_v2(a,'create_message',p)->>'id')::uuid=message);
 perform test.reject('one message per place',format('select public.pilgrimage_v2(%L,''create_message'',%L)',a,(p||jsonb_build_object('id',gen_random_uuid()))::text),'duplicate');
 perform test.reject('cannot edit another author',format('select public.pilgrimage_v2(%L,''update_content'',%L)',b,jsonb_build_object('id',message,'body','篡改')::text),'自己的');
 perform public.pilgrimage_v2(a,'favorite','{"location_id":"test-place","enabled":true}');
 perform test.ok('favorites isolated',not ((public.pilgrimage_v2(b,'self')->'favorites') ? 'test-place'));
 point=st_project(validate_fix(test.fix()),200.01,0);
 p=jsonb_build_object('location_id','test-place','fix',test.fix(st_y(point::geometry),st_x(point::geometry)));
 perform test.reject('200m outer boundary',format('select public.pilgrimage_v2(%L,''verify_visit'',%L)',a,p::text),'认证范围');
 point=st_project(validate_fix(test.fix()),199.99,0);
 p=jsonb_build_object('location_id','test-place','fix',test.fix(st_y(point::geometry),st_x(point::geometry)));
 r=public.pilgrimage_v2(a,'verify_visit',p);visit=(r->>'id')::uuid;
 perform test.ok('200m inner boundary',visit is not null);
 perform test.ok('raw GPS not stored in visit',r->>'latitude' is null and r->>'longitude' is null and r->>'distance_m' is not null);
 perform test.ok('private visit not visible to B',jsonb_array_length(public.pilgrimage_v2(b,'content','{"location_id":"test-place","kind":"visit"}'))=0);
 perform test.ok('admin has no private photo access',jsonb_array_length(public.pilgrimage_v2(admin,'content','{"location_id":"test-place","kind":"visit"}'))=0);
 perform public.pilgrimage_v2(a,'delete_content',jsonb_build_object('id',visit));
 perform test.ok('deleting visit note preserves certification',exists(select 1 from content where id=visit and verified_at is not null));
 asset1=test.asset(a);
 perform test.ok('ready upload reservation is idempotent',(public.pilgrimage_v2(a,'media_reserve',jsonb_build_object('request_id',(select request_id from media_assets where id=asset1),'size_bytes',100,'sha256',repeat('a',64)))->>'id')::uuid=asset1);
 perform test.reject('request ID cannot change image bytes',format('select public.pilgrimage_v2(%L,''media_reserve'',%L)',a,jsonb_build_object('request_id',(select request_id from media_assets where id=asset1),'size_bytes',100,'sha256',repeat('b',64))::text),'另一张图片');
 perform public.pilgrimage_v2(a,'media_cancel',jsonb_build_object('id',asset1));
 perform test.reject('cancelled reservation reports cleanup instead of duplicate',format('select public.pilgrimage_v2(%L,''media_reserve'',%L)',a,jsonb_build_object('request_id',(select request_id from media_assets where id=asset1),'size_bytes',100,'sha256',repeat('a',64))::text),'正在清理');
 perform test.reject('cancelled reservation cannot become ready',format('select public.pilgrimage_v2(%L,''media_ready'',%L)',a,jsonb_build_object('id',asset1)::text),'预留已失效');
 p=jsonb_build_object('request_id',(select request_id from media_assets where id=asset1),'size_bytes',100,'sha256',repeat('a',64));
 perform public.pilgrimage_v2_cleanup(a,'removed',asset1);
 r=public.pilgrimage_v2(a,'media_reserve',p);
 p=public.pilgrimage_v2_cleanup(a,'abort_upload',(r->>'id')::uuid);
 perform test.ok('failed readiness marks unlinked upload for cleanup',
  p->>'path' is not null and
  exists(select 1 from media_assets where id=(r->>'id')::uuid and state='deleting'));
 perform public.pilgrimage_v2_cleanup(a,'removed',(r->>'id')::uuid);
 p=jsonb_build_object('request_id',(r->>'request_id')::uuid,'size_bytes',100,'sha256',repeat('a',64));
 r=public.pilgrimage_v2(a,'media_reserve',p);
 perform test.ok('same request can retry after actual cleanup',(r->>'id')::uuid<>asset1);
 asset1=(r->>'id')::uuid;perform public.pilgrimage_v2(a,'media_ready',r);
 p=jsonb_build_object('scene_id','test-scene','fix',test.fix(),'media_id',asset1,'visibility','public');
 r=public.pilgrimage_v2(a,'publish_recreation',p);recreation=(r->>'id')::uuid;
 p=public.pilgrimage_v2_cleanup(a,'abort_upload',asset1);
 perform test.ok('failed parallel upload cannot remove linked photo',(p->>'linked')::boolean and (select state='ready' from media_assets where id=asset1));
 perform test.ok('recreation also certifies visit',(select count(*) from content where user_id=a and location_id='test-place' and kind='visit')=1);
 perform public.pilgrimage_v2(b,'like',jsonb_build_object('id',recreation,'enabled',true));
 perform public.pilgrimage_v2(b,'report',jsonb_build_object('id',recreation,'reason','版权问题'));
 asset2=test.asset(a);
 r=public.pilgrimage_v2(a,'publish_recreation',jsonb_build_object('scene_id','test-scene','media_id',asset2));
 perform test.ok('remote replacement keeps one recreation',(select count(*) from content where user_id=a and kind='recreation')=1);
 perform test.ok('replacement clears old likes',not exists(select 1 from likes where content_id=recreation));
 perform test.ok('old report remains version bound',exists(select 1 from reports where target_id=recreation and target_version=1 and snapshot->>'media_id'=asset1::text));
 perform test.ok('replacement retires old media',(select state='deleting' from media_assets where id=asset1));
 perform public.pilgrimage_v2_cleanup(a,'removed',asset1);
 perform public.pilgrimage_v2(admin,'admin_hide',jsonb_build_object('id',recreation,'hidden',true));
 perform test.reject('cannot self-restore hidden content',format('select public.pilgrimage_v2(%L,''update_content'',%L)',a,jsonb_build_object('id',recreation,'body','修改')::text),'隐藏');
 perform test.reject('cannot replace hidden recreation',format('select public.pilgrimage_v2(%L,''publish_recreation'',%L)',a,jsonb_build_object('scene_id','test-scene','media_id',test.asset(a))::text),'隐藏');
 perform test.ok('hidden entry still manageable by author',jsonb_array_length(public.pilgrimage_v2(a,'content','{"mine":true,"kind":"recreation"}'))=1);
 perform public.pilgrimage_v2(a,'make_private',jsonb_build_object('id',recreation));
 perform test.reject('admin cannot read newly private media',format('select public.pilgrimage_v2(%L,''media'',%L)',admin,jsonb_build_object('id',asset2)::text),'无权');
 perform set_config('request.jwt.claim.sub',b::text,true);
 set local role authenticated;
 select jsonb_build_object('count',count(*)) into r from v2.content where id=recreation;
 reset role;
 perform test.ok('RLS blocks direct private content read',(r->>'count')::int=0);
 perform set_config('request.jwt.claim.sub',admin::text,true);
 set local role authenticated;
 select jsonb_build_object('count',count(*)) into r from v2.media_assets where id=asset2;
 reset role;
 perform test.ok('RLS blocks admin direct private media read',(r->>'count')::int=0);
 p=jsonb_build_object('id',gen_random_uuid(),'body','胶囊','song','歌','artist','歌手','place_name','当前地点','latitude',30,'longitude',120,'fix',test.fix());
 perform public.pilgrimage_v2(a,'create_capsule',p);
 perform test.reject('nearby duplicate capsule',format('select public.pilgrimage_v2(%L,''create_capsule'',%L)',a,(p||jsonb_build_object('id',gen_random_uuid()))::text),'胶囊');
 point=st_project(validate_fix(test.fix()),100.01,0);
 p=p||jsonb_build_object('id',gen_random_uuid(),'latitude',st_y(point::geometry),'longitude',st_x(point::geometry),'fix',test.fix(st_y(point::geometry),st_x(point::geometry)));
 perform public.pilgrimage_v2(a,'create_capsule',p);
 perform test.ok('100m capsule separation accepted',(select count(*) from content where user_id=a and kind='capsule')=2);
 perform public.pilgrimage_v2(admin,'admin_status',jsonb_build_object('id',a,'disabled',true));
 perform test.reject('disabled user cannot edit',format('select public.pilgrimage_v2(%L,''update_content'',%L)',a,jsonb_build_object('id',message,'body','编辑')::text),'账号暂不能');
 perform public.pilgrimage_v2(a,'favorite','{"location_id":"test-place","enabled":false}');
 perform test.ok('disabled user can manage favorites',not exists(select 1 from favorites where user_id=a));
 perform public.pilgrimage_v2(admin,'admin_status',jsonb_build_object('id',a,'disabled',false));
 perform public.pilgrimage_v2(admin,'revoke_badge',jsonb_build_object('user_id',a,'badge_id','first_message'));
 perform award(a,'first_message');
 perform test.ok('revoked badge not automatically reawarded',not exists(select 1 from user_badges where user_id=a and badge_id='first_message'));
 insert into challenge_schedule values((now() at time zone 'Asia/Shanghai')::date,'test-choice');
 perform test.ok('unanswered question omits secret answers',not ((public.pilgrimage_v2(a,'challenges')->0)?'correct_option') and not ((public.pilgrimage_v2(a,'challenges')->0)?'answer_latitude'));
 r=public.pilgrimage_v2(a,'answer','{"question_id":"test-choice","option":"1"}');
 perform test.ok('first wrong result officially saved',not(r->>'practice')::boolean and not(r->>'correct')::boolean);
 r=public.pilgrimage_v2(a,'answer','{"question_id":"test-choice","option":"0"}');
 perform test.ok('replay is practice',(r->>'practice')::boolean and (r->>'correct')::boolean);
 perform test.ok('replay cannot overwrite first score',(select count(*) from challenge_attempts where user_id=a)=1 and not(select correct from challenge_attempts where user_id=a));
 insert into questions(id,challenge_type,question,answer_latitude,answer_longitude,correct_radius_m,explanation,published) values('test-map','map_guess','隔离地图题',30,120,200,'仅用于边界测试',true);
 insert into challenge_schedule values((now() at time zone 'Asia/Shanghai')::date-1,'test-map');
 point=st_project(validate_fix(test.fix()),200.01,0);
 r=public.pilgrimage_v2(a,'answer',jsonb_build_object('question_id','test-map','latitude',st_y(point::geometry),'longitude',st_x(point::geometry)));
 perform test.ok('map answer uses real PostGIS distance',not (r->>'correct')::boolean and (r->>'distance_m')::double precision>200);
 r=public.pilgrimage_v2(a,'answer','{"question_id":"test-map","latitude":30,"longitude":120}');
 perform test.ok('map replay preserves official incorrect score',(r->>'practice')::boolean and (r->>'correct')::boolean and not(select correct from challenge_attempts where user_id=a and question_id='test-map'));
 for i in 1..10 loop
  insert into questions(id,challenge_type,question,options,correct_option,explanation,published) select 'test-badge-'||i,challenge_type,question,options,correct_option,explanation,true from questions where id='test-choice';
  insert into challenge_schedule values((now() at time zone 'Asia/Shanghai')::date-i-1,'test-badge-'||i);
  perform public.pilgrimage_v2(a,'answer',jsonb_build_object('question_id','test-badge-'||i,'option','0'));
 end loop;
 perform test.ok('ten completed and ten correct badges awarded once',(select count(*) from user_badges where user_id=a and badge_id in ('ten_challenges','ten_correct'))=2);
 insert into questions(id,challenge_type,question,options,correct_option,explanation,published) select 'test-future',challenge_type,question,options,correct_option,explanation,true from questions where id='test-choice';
 insert into challenge_schedule values((now() at time zone 'Asia/Shanghai')::date+1,'test-future');
 perform test.ok('future Shanghai challenge not readable',not exists(select 1 from jsonb_array_elements(public.pilgrimage_v2(a,'challenges')) item where item->>'id'='test-future'));
 perform test.reject('future challenge cannot be answered',format('select public.pilgrimage_v2(%L,''answer'',''{"question_id":"test-future","option":"0"}'')',a),'尚未发布');
 perform public.pilgrimage_v2(a,'account_begin');
 perform test.reject('deleting account cannot write',format('select public.pilgrimage_v2(%L,''favorite'',''{"location_id":"test-place","enabled":true}'')',a),'登录');
 perform public.pilgrimage_v2(a,'account_begin');
 perform public.pilgrimage_v2_cleanup(a,'account_finalize');
 perform test.ok('only anonymous message remains',exists(select 1 from content where id=message and user_id is null) and not exists(select 1 from content where user_id=a));
 perform test.ok('deleting status survives cleanup for retry',(select status='deleting' from profiles where id=a));
 delete from auth.users where id=a;
 perform test.ok('Auth final delete has no blocking foreign keys',not exists(select 1 from profiles where id=a));
 perform test.ok('late upload compensation identifies deleted reservation',(public.pilgrimage_v2_cleanup(a,'abort_upload',asset2)->>'missing')::boolean);
end$$;
rollback;
